import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"常见探测类型业界调研与 custos 差距分析","description":"","frontmatter":{"title":"常见探测类型业界调研与 custos 差距分析"},"headers":[],"relativePath":"guide/probe-survey.md","filePath":"guide/probe-survey.md","lastUpdated":1793346634000}`),a={name:`guide/probe-survey.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_26-探测类型业界调研与差距分析" tabindex="-1">26. 探测类型业界调研与差距分析 <a class="header-anchor" href="#_26-探测类型业界调研与差距分析" aria-label="Permalink to “26. 探测类型业界调研与差距分析”">​</a></h1><h2 id="_26-1-概述" tabindex="-1">26.1 概述 <a class="header-anchor" href="#_26-1-概述" aria-label="Permalink to “26.1 概述”">​</a></h2><p>本文调研业界主流监控/探测工具内置的常见检查类型，与 <code>custos-probe</code> 当前内置探测能力对比，产出差距分析，作为「custos 内置零插件基础探测面」的规划输入。调研范围：Nagios/Monitoring Plugins 插件生态、Prometheus blackbox_exporter、Uptime Kuma、Sensu 插件集、Centreon 插件/连接器、Zabbix agent 采集键、Windows 侧 NSClient++/check_nt（服务/事件日志）、OpenWrt UBUS 探测面。</p><p><strong>调研范围与主要来源：</strong></p><ul><li><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">Monitoring Plugins 手册页索引（check_* 全清单）</a></li><li><a href="https://github.com/nagios-plugins/nagios-plugins/tree/master/plugins" target="_blank" rel="noreferrer">nagios-plugins 源码目录（plugins/）</a></li><li><a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">Prometheus blackbox_exporter 配置文档（prober 类型）</a></li><li><a href="https://github.com/prometheus/blackbox_exporter/blob/master/README.md" target="_blank" rel="noreferrer">blackbox_exporter README</a></li><li><a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma README（监控类型清单）</a></li><li><a href="https://sensu.io/resources/plugins" target="_blank" rel="noreferrer">Sensu 官方插件页（process/disk/memory/http/docker checks）</a></li><li><a href="https://github.com/centreon/centreon-plugins" target="_blank" rel="noreferrer">Centreon centreon-plugins 仓库（可监控对象清单）</a></li><li><a href="https://www.centreon.com/connectors/" target="_blank" rel="noreferrer">Centreon 连接器总览（700+ 连接器分类）</a></li><li><a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix agent 采集键文档</a></li><li><a href="https://nsclient.org/docs/scenarios/service-monitoring" target="_blank" rel="noreferrer">NSClient++ 服务与进程监控场景</a></li><li><a href="https://nsclient.org/docs/reference/windows/CheckEventLog" target="_blank" rel="noreferrer">NSClient++ CheckEventLog 参考</a></li><li><a href="https://support.nagios.com/kb/print-775.html" target="_blank" rel="noreferrer">Nagios XI 知识库：Service Checks（Windows 服务/事件日志多种查法）</a></li><li><a href="https://www.nagios.com/solutions/Windows-monitoring" target="_blank" rel="noreferrer">Nagios Windows 监控方案页</a></li><li><a href="https://openwrt.org/docs/techref/ubus" target="_blank" rel="noreferrer">OpenWrt Wiki：ubus 微总线架构</a></li></ul><p><strong>custos 现状摘要</strong>（证据来自仓库）：</p><ul><li>已内置探针仅两种：<code>ProcessProbe</code>（pid 文件存活，本地路径 <code>crates/custos-probe/src/process.rs:10</code>，工厂分支 <code>crates/custos-probe/src/factory.rs:29</code>）与 <code>ExecProbe</code>（受控命令执行：超时、输出上限、超时杀进程树，<code>crates/custos-probe/src/exec.rs:69</code>、<code>crates/custos-probe/src/exec.rs:211</code>，工厂分支 <code>crates/custos-probe/src/factory.rs:37</code>）。</li><li>资源类型 <code>custom-command</code>、<code>network-connectivity</code>、<code>http-endpoint</code>、<code>proxy</code>、<code>tunnel</code>、<code>service</code> 在工厂里<strong>全部委托给 ExecProbe</strong>，由用户在 config 里自备命令（<code>crates/custos-probe/src/factory.rs:37-42</code>）——即这些类型<strong>没有原生实现</strong>，开箱即用能力为零插件目标下的主要缺口。</li></ul><p>优先级按自愈引擎场景评定：高 = 覆盖最常见故障且是自愈触发的主要信号源；中 = 常见但可暂由 exec 兜底或场景较窄；低 = 长尾/特定行业。</p><h2 id="_26-2-进程-服务" tabindex="-1">26.2 进程 / 服务 <a class="header-anchor" href="#_26-2-进程-服务" aria-label="Permalink to “26.2 进程 / 服务”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>进程存活（pid 文件）</td><td>Nagios <a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_procs</a>、<a href="https://nsclient.org/docs/scenarios/service-monitoring" target="_blank" rel="noreferrer">NSClient++ check_process</a>、<a href="https://sensu.io/resources/plugins" target="_blank" rel="noreferrer">Sensu process-checks</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix proc.num</a></td><td>✅ <code>crates/custos-probe/src/process.rs:10</code>（工厂 <code>factory.rs:29</code>）</td><td>高（已有）</td><td>—</td></tr><tr><td>受控命令执行（exec）</td><td><a href="https://docs.sensu.io/sensu-go/6.1/operations/monitor-sensu/monitor-sensu-with-sensu" target="_blank" rel="noreferrer">Sensu check 执行模型</a>、NRPE/check_by_ssh 模式</td><td>✅ <code>crates/custos-probe/src/exec.rs:69</code>（工厂 <code>factory.rs:37</code>）</td><td>高（已有）</td><td>—</td></tr><tr><td>systemd unit 状态（active/substate）</td><td><a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix systemd.unit.info</a>、<a href="https://nsclient.org/docs/scenarios/service-monitoring" target="_blank" rel="noreferrer">NSClient++ check_service（Linux systemd）</a></td><td>❌ 无（<code>service</code> 类型仅委托 exec，<code>factory.rs:42</code>）</td><td>高</td><td>直接读 <code>systemctl show -p ActiveState,SubState</code> 或调 D-Bus org.freedesktop.systemd1，输出归一化为 Healthy/Unhealthy</td></tr><tr><td>Windows 服务状态（Started/Stopped、自动启动未运行告警）</td><td><a href="https://nsclient.org/docs/scenarios/service-monitoring" target="_blank" rel="noreferrer">NSClient++ check_service</a>、<a href="https://support.nagios.com/kb/print-775.html" target="_blank" rel="noreferrer">check_nt SERVICESTATE</a>、<a href="https://www.nagios.com/solutions/Windows-monitoring" target="_blank" rel="noreferrer">Nagios XI Windows 方案</a></td><td>❌ 无（同上委托 exec）</td><td>高</td><td><code>sc query &lt;name&gt;</code> 或 Windows API QueryServiceStatus；比对 StartType=auto 且 state≠RUNNING 判 Unhealthy</td></tr><tr><td>Docker 容器状态（running/重启次数）</td><td><a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma Docker Containers</a>、<a href="https://sensu.io/resources/plugins" target="_blank" rel="noreferrer">Sensu Docker 插件</a>、<a href="https://github.com/centreon/centreon-plugins" target="_blank" rel="noreferrer">Centreon Docker</a></td><td>❌ 无</td><td>高</td><td>复用 ExecProbe 跑 <code>docker inspect -f &#39;&lt;Go 模板: State.Status&gt;&#39; &lt;name&gt;</code>，或走 /var/run/docker.sock 的 HTTP API（GET /containers/{id}/json）</td></tr><tr><td>进程级资源占用（CPU/内存/句柄数阈值）</td><td><a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix proc.mem / proc.cpu.util</a>、<a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_procs 内存阈值</a></td><td>❌ 无</td><td>中</td><td>Linux 读 <code>/proc/&lt;pid&gt;/stat{,m}</code> 换算；作为 process 探针的可选阈值参数扩展</td></tr><tr><td>Windows 事件日志（error/critical 条目数、event id 过滤）</td><td><a href="https://nsclient.org/docs/reference/windows/CheckEventLog" target="_blank" rel="noreferrer">NSClient++ CheckEventLog</a>、<a href="https://www.nagios.com/solutions/Windows-monitoring" target="_blank" rel="noreferrer">Nagios XI 事件日志向导</a></td><td>❌ 无</td><td>中</td><td>Windows 用 Windows EID/<code>wevtutil qe</code> + 时间窗与 level 过滤；归一化为「时间窗内 error 条数」</td></tr></tbody></table><h2 id="_26-3-http-tcp-端口" tabindex="-1">26.3 HTTP / TCP / 端口 <a class="header-anchor" href="#_26-3-http-tcp-端口" aria-label="Permalink to “26.3 HTTP / TCP / 端口”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>HTTP(S) 状态码/响应时间</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_http</a>、<a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox_exporter http prober</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma HTTP(s)</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix net.tcp.service[https]</a></td><td>❌ 无原生（<code>http-endpoint</code> 类型仅委托 exec，<code>factory.rs:39</code>）</td><td>高</td><td>reqwest（关闭重定向可选），校验 status∈白名单 + 响应时间阈值；复用 exec.rs 的超时模型</td></tr><tr><td>HTTP 关键字/正则匹配</td><td><a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma HTTP(s) Keyword</a>、<a href="https://github.com/nagios-plugins/nagios-plugins/tree/master/plugins" target="_blank" rel="noreferrer">check_http -r/-s</a>、<a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox fail_if_matches_regexp</a></td><td>❌ 无</td><td>高</td><td>与上同一次请求内做 body 正则 contains/matches 断言，避免二次请求</td></tr><tr><td>HTTP JSON 断言（json path/值比较）</td><td><a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma HTTP(s) Json Query</a></td><td>❌ 无</td><td>中</td><td>serde_json + 简化 dot-path 取值比较（<code>$.status == &quot;ok&quot;</code>）</td></tr><tr><td>TCP 端口连通</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_tcp</a>、<a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox tcp prober</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma Port</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix net.tcp.port</a></td><td>❌ 无（<code>network-connectivity</code> 类型仅委托 exec，<code>factory.rs:38</code>）</td><td>高</td><td><code>TcpStream::connect_timeout</code>，记录连接耗时；可选 starttls/TLS 握手</td></tr><tr><td>ICMP Ping（丢包/时延）</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_ping / check_fping</a>、<a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox icmp prober</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma Ping</a></td><td>❌ 无</td><td>高</td><td>用 <code>servo</code>/<code>ping</code> crate（注意 raw socket 权限，Windows 需 IcmpSendEcho API 或降级为 TCP ping）</td></tr><tr><td>协议握手（ssh/smtp/imap/pop/ldap/ftp banner）</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_ssh / check_smtp / check_imap / check_pop / check_ldap / check_ftp</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix net.tcp.service 服务清单</a></td><td>❌ 无</td><td>中</td><td>先 TCP 连接再读 greeting/发探测串匹配期望应答；先做 ssh+smtp 两个最常用的</td></tr><tr><td>gRPC 健康检查（grpc.health.v1）</td><td><a href="https://github.com/prometheus/blackbox_exporter/blob/master/README.md" target="_blank" rel="noreferrer">blackbox grpc prober</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma gRPC</a></td><td>❌ 无</td><td>中</td><td>tonic + 标准 health proto，Invoke Health check 期望 SERVING</td></tr><tr><td>UDP 服务探测</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_udp</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix net.udp.service</a></td><td>❌ 无</td><td>中</td><td>发送 payload + 期望响应正则 + 超时；DNS/NTP 可作专用探针代替</td></tr><tr><td>WebSocket 握手</td><td><a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox websocket prober</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma Websocket</a></td><td>❌ 无</td><td>低</td><td>tokio-tungstenite 完成握手即可判定存活，可选发送/期待消息</td></tr><tr><td>MQTT 连接</td><td>Uptime Kuma 支持 MQTT 监控（<a href="https://www.facebook.com/thenewstack/posts/uptime-kuma-can-monitor-several-services-including-ping-https-mysql-tcp-port-smt/1749382069827313/" target="_blank" rel="noreferrer">社区转述</a>，官方 README 未逐条列出，待核）</td><td>❌ 无</td><td>低</td><td>rumqttc 连接 + subscribe 主题成功即 Healthy</td></tr><tr><td>RADIUS 认证探测</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_radius</a></td><td>❌ 无</td><td>低</td><td>Access-Request 包 + 期望 Access-Accept；使用率低，可留给 exec 兜底</td></tr></tbody></table><h2 id="_26-4-文件" tabindex="-1">26.4 文件 <a class="header-anchor" href="#_26-4-文件" aria-label="Permalink to “26.4 文件”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>文件存在/年龄/大小阈值</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_file_age</a></td><td>❌ 无</td><td>中</td><td>元数据检查：exists + mtime 年龄上限 + size 下限，纯 std 无外部依赖</td></tr><tr><td>日志文件关键字监控（新增行匹配 error）</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_log</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix log/log.count/logrt</a></td><td>❌ 无</td><td>高</td><td>记录 offset 状态，增量读新行做正则匹配，命中即 Unhealthy（自愈引擎里“日志里出现 panic/OOM”是核心触发信号）；轮转按 inode 检测</td></tr></tbody></table><h2 id="_26-5-磁盘-系统指标" tabindex="-1">26.5 磁盘 / 系统指标 <a class="header-anchor" href="#_26-5-磁盘-系统指标" aria-label="Permalink to “26.5 磁盘 / 系统指标”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>磁盘空间（百分比/绝对值阈值）</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_disk</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix vfs.fs.size</a>、<a href="https://sensu.io/resources/plugins" target="_blank" rel="noreferrer">Sensu disk-checks</a>、<a href="https://support.nagios.com/kb/category.php?id=186" target="_blank" rel="noreferrer">Nagios Disk Space Checks</a></td><td>❌ 无</td><td>高</td><td>Linux <code>statvfs</code>（nix crate），Windows <code>GetDiskFreeSpaceExW</code>；挂载点 + warn/crit 双阈值</td></tr><tr><td>inode 使用率</td><td><a href="https://github.com/sensu-plugins/sensu-plugins-disk-checks" target="_blank" rel="noreferrer">Sensu check-disk-usage -K/-W</a>、<a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_disk</a></td><td>❌ 无</td><td>低</td><td>与磁盘空间探针同函数返回 files/ffree，加 inode 阈值参数即可</td></tr><tr><td>内存使用（含 available 语义）</td><td><a href="https://sensu.io/resources/plugins" target="_blank" rel="noreferrer">Sensu memory-checks</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix vm.memory.size</a>、<a href="https://support.nagios.com/kb/category.php?id=186" target="_blank" rel="noreferrer">check_ram（Nagios 库）</a></td><td>❌ 无</td><td>高</td><td>Linux 读 <code>/proc/meminfo</code> 的 MemAvailable；Windows GlobalMemoryStatusEx</td></tr><tr><td>CPU 使用率 / 负载</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_load</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix system.cpu.util / system.cpu.load</a></td><td>❌ 无</td><td>高</td><td>负载：读 <code>/proc/loadavg</code> 与核数比值；CPU%：两次采样 /proc/stat 差分</td></tr><tr><td>swap 使用</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_swap</a></td><td>❌ 无</td><td>中</td><td>Linux <code>/proc/meminfo</code> SwapTotal/SwapFree；随内存探针一并实现成本低</td></tr><tr><td>NTP 时钟偏移</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_ntp_time / check_ntp_peer</a></td><td>❌ 无</td><td>中</td><td>简单 SNTP 客户端（UDP 123，一次往返算 offset），阈值告警</td></tr><tr><td>登录用户数</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_users</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix system.users.num</a></td><td>❌ 无</td><td>低</td><td>解析 <code>utmp</code> 或跑 <code>who | wc -l</code>，场景有限可后置</td></tr><tr><td>SMART/硬件传感器</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_ide_smart / check_sensors</a>、<a href="https://github.com/sensu-plugins/sensu-plugins-disk-checks" target="_blank" rel="noreferrer">Sensu check-smart</a>、<a href="https://www.centreon.com/connectors/" target="_blank" rel="noreferrer">Centreon Hardware 类连接器</a></td><td>❌ 无</td><td>低</td><td>委托 <code>smartctl -H</code> 输出判 OK；硬件传感器走 lm-sensors 输出解析</td></tr><tr><td>UPS 状态</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_ups</a>、<a href="https://www.centreon.com/connectors/" target="_blank" rel="noreferrer">Centreon UPS-PDU 类</a></td><td>❌ 无</td><td>低</td><td>走 NUT 协议（upsmon/upsrw）判定 OB/LB 状态</td></tr></tbody></table><h2 id="_26-6-数据库" tabindex="-1">26.6 数据库 <a class="header-anchor" href="#_26-6-数据库" aria-label="Permalink to “26.6 数据库”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>MySQL/MariaDB 连通 + 轻量查询</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_mysql / check_mysql_query</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma MySQL</a>、<a href="https://www.centreon.com/connectors/" target="_blank" rel="noreferrer">Centreon MySQL/MariaDB 连接器</a></td><td>❌ 无</td><td>中</td><td>mysql_async 执行 <code>SELECT 1</code> + 可选阈值查询；连接失败/超时分别归一化</td></tr><tr><td>PostgreSQL 连通 + 查询</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_pgsql</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma PostgreSQL</a>、<a href="https://www.centreon.com/connectors/" target="_blank" rel="noreferrer">Centreon PostgreSQL</a></td><td>❌ 无</td><td>中</td><td>tokio-postgres <code>SELECT 1</code>；可扩展 <code>pg_is_in_recovery()</code> 等只读断言</td></tr><tr><td>Redis 连通</td><td><a href="https://github.com/centreon/centreon-plugins" target="_blank" rel="noreferrer">Centreon Redis</a>、<a href="https://www.facebook.com/thenewstack/posts/uptime-kuma-can-monitor-several-services-including-ping-https-mysql-tcp-port-smt/1749382069827313/" target="_blank" rel="noreferrer">Uptime Kuma Redis</a></td><td>❌ 无</td><td>中</td><td>redis crate 发 <code>PING</code> 期待 <code>PONG</code>，可选 INFO 指标阈值</td></tr><tr><td>其它数据库（MSSQL/Oracle/Mongo）</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_mssql / check_oracle / check_dbi</a>、<a href="https://github.com/centreon/centreon-plugins" target="_blank" rel="noreferrer">Centreon Databases 分类</a></td><td>❌ 无</td><td>低</td><td>长尾，先用 ExecProbe 兜底（<code>sqlcmd</code>/<code>psql</code> 等），有需求再原生</td></tr></tbody></table><h2 id="_26-7-容器-虚拟化" tabindex="-1">26.7 容器 / 虚拟化 <a class="header-anchor" href="#_26-7-容器-虚拟化" aria-label="Permalink to “26.7 容器 / 虚拟化”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>Docker 容器状态</td><td>见 26.2 行</td><td>❌ 无</td><td>高</td><td>见 26.2 行</td></tr><tr><td>Kubernetes 工作负载（pod/deployment 就绪）</td><td>未找到公开资料（待核；Centreon/Zabbix 均有 K8s 方案但本次未取证）</td><td>❌ 无</td><td>低</td><td>kube API GET /apis/apps/v1/namespaces/ns/deployments 比对 readyReplicas；依赖面大，最后做</td></tr></tbody></table><h2 id="_26-8-证书-dns" tabindex="-1">26.8 证书 / DNS <a class="header-anchor" href="#_26-8-证书-dns" aria-label="Permalink to “26.8 证书 / DNS”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>TLS 证书到期/证书链校验</td><td><a href="https://github.com/nagios-plugins/nagios-plugins/tree/master/plugins" target="_blank" rel="noreferrer">check_http -D（证书到期）</a>、<a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox probe_ssl_oui/证书链校验</a>、<a href="https://sensu.io/resources/plugins" target="_blank" rel="noreferrer">Sensu HTTP 插件 SSL expiry</a></td><td>❌ 无</td><td>高</td><td>rustls/native-tls 拿 peer 证书 not_after，剩余天数阈值（&lt;30 warn，&lt;7 crit 是业界惯例）；不依赖 HTTP 探针可对任意 host:port 做</td></tr><tr><td>DNS 记录解析（A/AAAA/CNAME + 应答匹配）</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_dns / check_dig</a>、<a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox dns prober</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma DNS Record</a>、<a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix net.dns.record</a></td><td>❌ 无</td><td>高</td><td>hickory-resolver（trust-dns）指定 resolver server + record type + 应答正则断言</td></tr><tr><td>DoT/DoH</td><td><a href="https://github.com/prometheus/blackbox_exporter/blob/master/CONFIGURATION.md" target="_blank" rel="noreferrer">blackbox dns_over_tls</a>（DoT）；DoH 未找到公开资料（待核）</td><td>❌ 无</td><td>低</td><td>DoT：TLS 853 端口复用 DNS 探针；DoH 后置</td></tr></tbody></table><h2 id="_26-9-网络设备-基础网络" tabindex="-1">26.9 网络设备 / 基础网络 <a class="header-anchor" href="#_26-9-网络设备-基础网络" aria-label="Permalink to “26.9 网络设备 / 基础网络”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>SNMP OID 采集/阈值</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_snmp</a>、<a href="https://www.centreon.com/connectors/" target="_blank" rel="noreferrer">Centreon 700+ SNMP 连接器</a>、<a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma SNMP</a></td><td>❌ 无</td><td>中</td><td>snmp crate（v2c/v3），OID 采样 + 阈值比较；网络设备场景的事实标准</td></tr><tr><td>接口状态/流量（up/down、误码）</td><td><a href="https://zabbix.com/documentation/current/en/manual/config/items/itemtypes/zabbix_agent" target="_blank" rel="noreferrer">Zabbix net.if.in / net.if.discovery</a>、<a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_ifstatus / check_ifoperstatus</a></td><td>❌ 无</td><td>中</td><td>本机：读 <code>/sys/class/net/&lt;if&gt;/operstate</code> + statistics；远端：SNMP ifTable</td></tr><tr><td>OpenWrt/UBUS 探测面（network.interface status、service list、device 状态）</td><td><a href="https://openwrt.org/docs/techref/ubus" target="_blank" rel="noreferrer">OpenWrt ubus：<code>ubus call network.interface.wan status</code>、<code>ubus call service list</code></a></td><td>❌ 无</td><td>中</td><td>custos 若面向软路由/网关场景：通过 ubus socket（/var/run/ubus.sock）JSON-RPC 调 <code>network.interface.&lt;name&gt;.status</code> 的 <code>up</code> 字段与 <code>service.list</code>；与 docs/guide/probe-diagnosis.md §5.1 的 Wi-Fi/IP/网关探针链天然衔接</td></tr><tr><td>DHCP 服务探测</td><td><a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_dhcp</a></td><td>❌ 无</td><td>低</td><td>发 DHCPDISCOVER 广播等 OFFER；需要 raw socket 权限，长尾</td></tr></tbody></table><h2 id="_26-10-其它" tabindex="-1">26.10 其它 <a class="header-anchor" href="#_26-10-其它" aria-label="Permalink to “26.10 其它”">​</a></h2><table tabindex="0"><thead><tr><th>探测类型</th><th>业界谁在用</th><th>custos 现状</th><th>优先级</th><th>实现要点建议（未实现）</th></tr></thead><tbody><tr><td>VPN/隧道端到端验证（不只是端口通，而是经隧道取到预期内容）</td><td>无单一标准实现（check_http 经代理模式 <code>-I proxy</code> 最接近，<a href="https://www.monitoring-plugins.org/doc/man/index.html" target="_blank" rel="noreferrer">check_http 手册</a>）</td><td>⚠️ <code>tunnel</code>/<code>proxy</code> 类型存在但仅委托 exec（<code>factory.rs:40-41</code>），无原生语义</td><td>中</td><td>原生化：隧道资源上跑&quot;通过隧道发起 HTTP/TCP 请求并断言出口 IP/目标可达&quot;，把探测面与自愈动作（重拨/重启隧道）对齐</td></tr><tr><td>Push/主动心跳（被监控端主动上报，超时判死）</td><td><a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma Push</a></td><td>❌ 无</td><td>低</td><td>自愈引擎多为主动探测模型，心跳模型引入状态存储；按需后置</td></tr><tr><td>游戏服务器（Steam/Source）</td><td><a href="https://github.com/louislam/uptime-kuma" target="_blank" rel="noreferrer">Uptime Kuma Steam Game Server</a></td><td>❌ 无</td><td>低</td><td>A2S 查询协议，长尾</td></tr></tbody></table><h2 id="_26-11-建议实现顺序" tabindex="-1">26.11 建议实现顺序 <a class="header-anchor" href="#_26-11-建议实现顺序" aria-label="Permalink to “26.11 建议实现顺序”">​</a></h2><p>依据：自愈引擎需要<strong>零插件就能覆盖最常见的自愈触发信号</strong>；先做&quot;高频故障 + 实现成本低&quot;的，再做依赖重的。</p><ol><li><strong>HTTP(S) 端点探测</strong>（状态码 + 关键字 + 响应时间）——最常见的存活/质量信号；一次请求覆盖三件事（26.3 前两行）。</li><li><strong>TCP 端口连通</strong> —— 最小实现（connect_timeout），是网络类诊断链的基元。</li><li><strong>DNS 解析</strong> —— 与 TCP/HTTP 组成完整网络诊断链（对应 probe-diagnosis.md §5.1 的证据链）。</li><li><strong>TLS 证书到期</strong> —— 复用 2/3 的 TLS 能力，纯阈值逻辑，自愈价值高（提前告警）。</li><li><strong>磁盘空间 / 内存 / CPU 负载</strong>（系统三件套，同一批实现，共享阈值模型）。</li><li><strong>日志文件关键字监控</strong>（增量 offset + 正则）——&quot;日志出现 panic/OOM&quot;是自愈引擎的高价值触发信号。</li><li><strong>systemd unit 状态</strong>（Linux <code>service</code> 类型的原生实现，替代委托 exec 的默认路径）。</li><li><strong>Docker 容器状态</strong> —— 容器化部署普及度高，实现走 docker.sock 或复用 ExecProbe。</li><li><strong>ICMP Ping</strong> —— 注意权限降级路径（无 raw socket 时 TCP ping 兜底）。</li><li><strong>文件存在/年龄 + swap</strong>（低成本补齐系统域）。</li><li><strong>Windows 服务状态 + 事件日志</strong>（有 Windows 部署需求时；custos exec/process 已有 Windows 分支，见 process.rs 的 tasklist/taskkill 路径）。</li><li><strong>MySQL/PostgreSQL/Redis 连通</strong>（数据库域按用户实际栈挑选）。</li><li><strong>SNMP 采集 + 接口状态</strong>（网络设备场景）。</li><li><strong>OpenWrt/UBUS 探测面</strong>（若软路由/网关是目标场景则提前到 3 之后）。</li><li>其余（gRPC/WebSocket/MQTT/UPS/SMART/K8s/Push 等）按需求长尾，继续由 ExecProbe 兜底。</li></ol><hr><p><em>本文档由 custos 探测能力调研生成；custos 代码证据基于 <code>crates/custos-probe</code>（process.rs 117 行 / exec.rs 338 行 / factory.rs 90 行）。外部工具能力以所附链接为准。</em></p>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};